INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(32845, 0, 0, 'You will suffer for this trespass!', 14, 0, 100, 0, 0, 15552, 'Hodir SAY_AGGRO'),
(32845, 1, 0, 'Tragic. To come so far, only to fail.', 14, 0, 100, 0, 0, 15553, 'Hodir SAY_SLAY_1'),
(32845, 1, 1, 'Welcome to the endless winter.', 14, 0, 100, 0, 0, 15554, 'Hodir SAY_SLAY_2'),
(32845, 2, 0, 'Winds of the north consume you!', 14, 0, 100, 0, 0, 15555, 'Hodir SAY_FLASH_FREEZE'),
(32845, 3, 0, '%s roars furiously.', 16, 0, 100, 0, 0, 15556, 'Hodir SAY_STALACTITE'),
(32845, 4, 0, 'I... I am released from his grasp... at last.', 14, 0, 100, 0, 0, 15557, 'Hodir SAY_DEATH'),
(32845, 5, 0, 'ENOUGH! This ends now!', 14, 0, 100, 0, 0, 15558, 'Hodir SAY_BERSERK'),
(32845, 6, 0, '%s shatters the Rare Cache of Hodir!', 16, 0, 100, 0, 0, 0, 'Hodir SAY_HARD_MODE_MISSED'),
(32845, 7, 0, '%s begins to cast Flash Freeze!', 41, 0, 100, 0, 0, 0, 'Hodir - EMOTE_FREEZE'),
(32845, 8, 0, '%s gains Frozen Blows!', 41, 0, 100, 0, 0, 0, 'Hodir - EMOTE_BLOW');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(32857, 0, 0, 'Whether the world\'s greatest gnats or the world\'s greatest heroes, you are still only mortal.', 14, 0, 100, 0, 0, 15684, 'Brundir - Aggro'),
(32857, 1, 0, 'A merciful kill!', 14, 0, 100, 0, 0, 15685, 'Brundir Slay 1'),
(32857, 1, 1, 'HAH!', 14, 0, 100, 0, 0, 15686, 'Brundir - Slay 2'),
(32857, 2, 0, 'Stand still and stare into the light!', 14, 0, 100, 0, 0, 15687, 'Brundir - Special'),
(32857, 3, 0, 'Let the storm clouds rise and rain down death from above!', 14, 0, 100, 0, 0, 15688, 'Brundir - Flight'),
(32857, 4, 0, 'The power of the storm lives on.', 14, 0, 100, 0, 0, 15689, 'Brundir - Death'),
(32857, 5, 0, 'You rush headlong into the maw of madness!', 14, 0, 100, 0, 0, 15690, 'Brundir - Encounter defeated'),
(32857, 6, 0, 'This meeting of the Assembly of Iron is adjourned!', 14, 0, 100, 0, 0, 15691, 'Brundir - Berserk'),
(32857, 7, 0, '%s begins to Overload!', 41, 0, 100, 0, 0, 0, 'Brundir - Overload');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(32865, 0, 0, 'Interlopers! You mortals who dare to interfere with my sport will pay... Wait--you...', 14, 0, 100, 0, 0, 15733, 'Thorim SAY_AGGRO_1'),
(32865, 1, 0, 'I remember you... In the mountains... But you... what is this? Where am--', 14, 0, 100, 0, 0, 15734, 'Thorim SAY_AGGRO_2'),
(32865, 2, 0, 'Do not hold back! Destroy them!', 14, 0, 100, 0, 0, 15736, 'Thorim SAY_SPECIAL'),
(32865, 3, 0, 'Impertinent whelps, you dare challenge me atop my pedestal? I will crush you myself!', 14, 0, 100, 0, 0, 15738, 'Thorim SAY_JUMPDOWN'),
(32865, 4, 0, 'Can\'t you at least put up a fight!?', 14, 0, 100, 0, 0, 15739, 'Thorim SAY_SLAY_1'),
(32865, 4, 1, 'Pathetic.', 14, 0, 100, 0, 0, 15740, 'Thorim SAY_SLAY_2'),
(32865, 5, 0, 'My patience has reached its limit!', 14, 0, 100, 0, 0, 15741, 'Thorim SAY_BERSERK'),
(32865, 6, 0, 'Failures! Weaklings!', 14, 0, 100, 0, 0, 15742, 'Thorim SAY_WIPE'),
(32865, 7, 0, 'Stay your arms! I yield!', 14, 0, 100, 0, 0, 15743, 'Thorim SAY_DEATH'),
(32865, 8, 0, 'I feel as though I am awakening from a nightmare, but the shadows in this place yet linger.', 14, 0, 100, 0, 0, 15744, 'Thorim SAY_END_NORMAL_1'),
(32865, 9, 0, 'Sif... was Sif here? Impossible--she died by my brother\'s hand. A dark nightmare indeed....', 14, 0, 100, 0, 0, 15745, 'Thorim SAY_END_NORMAL_2'),
(32865, 10, 0, 'I need time to reflect.... I will aid your cause if you should require it. I owe you at least that much. Farewell.', 14, 0, 100, 0, 0, 15746, 'Thorim SAY_END_NORMAL_3'),
(32865, 11, 0, 'You! Fiend! You are not my beloved! Be gone!', 14, 0, 100, 0, 0, 15747, 'Thorim SAY_END_HARD_1'),
(32865, 12, 0, 'Behold the hand behind all the evil that has befallen Ulduar, left my kingdom in ruins, corrupted my brother, and slain my wife.', 14, 0, 100, 0, 0, 15748, 'Thorim SAY_END_HARD_2'),
(32865, 13, 0, 'And now it falls to you, champions, to avenge us all. The task before you is great, but I will lend you my aid as I am able. You must prevail.', 14, 0, 100, 0, 0, 15749, 'Thorim SAY_END_HARD_3');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(32871, 0, 0, 'Translocation complete. Commencing planetary analysis of Azeroth.', 12, 0, 0, 0, 0, 15405, 'Algalon the Observer - SAY_ALGALON_INTRO_1'),
(32871, 1, 0, 'Stand back, mortals. I\'m not here to fight you.', 12, 0, 0, 0, 0, 15406, 'Algalon the Observer - SAY_ALGALON_INTRO_2'),
(32871, 2, 0, 'It is in the universe\'s best interest to re-originate this planet should my analysis find systemic corruption. Do not interfere.', 12, 0, 0, 0, 0, 15407, 'Algalon the Observer - SAY_ALGALON_INTRO_3'),
(32871, 3, 0, 'Your actions are illogical. All possible results for this encounter have been calculated. The Pantheon will receive the Observer\'s message regardless of outcome.', 14, 0, 0, 0, 0, 15386, 'Algalon the Observer - SAY_ALGALON_START_TIMER'),
(32871, 4, 0, 'See your world through my eyes: A universe so vast as to be immeasurable - incomprehensible even to your greatest minds.', 14, 0, 0, 1, 0, 15390, 'Algalon the Observer - SAY_ALGALON_AGGRO'),
(32871, 5, 0, 'The stars come to my aid!', 14, 0, 0, 0, 0, 15392, 'Algalon the Observer - SAY_ALGALON_COLLAPSING_STAR'),
(32871, 6, 0, '%s begins to Summon Collapsing Stars!', 41, 0, 0, 0, 0, 0, 'Algalon the Observer - EMOTE_ALGALON_COLLAPSING_STAR'),
(32871, 7, 0, 'Witness the fury of the cosmos!', 14, 0, 0, 0, 0, 15396, 'Algalon the Observer - SAY_ALGALONG_BIG_BANG'),
(32871, 8, 0, '%s begins to cast Big Bang!', 41, 0, 0, 0, 0, 0, 'Algalon the Observer - EMOTE_ALGALON_BIG_BANG'),
(32871, 9, 0, 'You are out of time.', 14, 0, 0, 0, 0, 15394, 'Algalon the Observer - SAY_ALGALON_ASCEND'),
(32871, 10, 0, '%s begins to cast Cosmic Smash!', 41, 0, 0, 0, 0, 0, 'Algalon the Observer - EMOTE_ALGALON_COSMIC_SMASH'),
(32871, 11, 0, 'Behold the tools of creation!', 14, 0, 0, 0, 0, 15397, 'Algalon the Observer - SAY_ALGALON_PHASE_TWO'),
(32871, 12, 0, 'I have seen worlds bathed in the Makers\' flames, their denizens fading without as much as a whimper. Entire planetary systems born and razed in the time that it takes your mortal hearts to beat once. Yet all throughout, my own heart devoid of emotion... of empathy. I. Have. Felt. Nothing. A million-million lives wasted. Had they all held within them your tenacity? Had they all loved life as you do?', 14, 0, 0, 1, 0, 15393, 'Algalon the Observer - SAY_ALGALON_OUTRO_1'),
(32871, 13, 0, 'Perhaps it is your imperfections... that which grants you free will... that allows you to persevere against all cosmically calculated odds. You prevail where the Titan\'s own perfect creations have failed.', 14, 0, 0, 1, 0, 15401, 'Algalon the Observer - SAY_ALGALON_OUTRO_2'),
(32871, 14, 0, 'I\'ve rearranged the reply code - your planet will be spared. I cannot be certain of my own calculations anymore.', 14, 0, 0, 1, 0, 15402, 'Algalon the Observer - SAY_ALGALON_OUTRO_3'),
(32871, 15, 0, 'I lack the strength to transmit the signal. You must... hurry... find a place of power... close to the skies.', 14, 0, 0, 1, 0, 15403, 'Algalon the Observer - SAY_ALGALON_OUTRO_4'),
(32871, 16, 0, 'Do not worry about my fate, Bronzen. If the signal is not transmitted in time, re-origination will proceed regardless. Save... your world...', 14, 0, 0, 1, 0, 15404, 'Algalon the Observer - SAY_ALGALON_OUTRO_5'),
(32871, 17, 0, 'Analysis complete. There is partial corruption in the planet\'s life-support systems as well as complete corruption in most of the planet\'s defense mechanisms.', 12, 0, 0, 0, 0, 15398, 'Algalon the Observer - SAY_ALGALON_DESPAWN_1'),
(32871, 18, 0, 'Begin uplink: Reply Code: \'Omega.\' Planetary re-origination requested.', 12, 0, 0, 0, 0, 15399, 'Algalon the Observer - SAY_ALGALON_DESPAWN_2'),
(32871, 19, 0, 'Farewell, mortals. Your bravery is admirable, for such flawed creatures.', 12, 0, 0, 0, 0, 15400, 'Algalon the Observer - SAY_ALGALON_DESPAWN_3'),
(32871, 20, 0, 'Loss of life unavoidable.', 14, 0, 0, 0, 0, 15387, 'Algalon the Observer - SAY_ALGALON_KILL'),
(32871, 20, 1, 'I do what I must.', 14, 0, 0, 0, 0, 15388, 'Algalon the Observer - SAY_ALGALON_KILL');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(32872, 0, 0, '%s surrounds itself with a crackling Runic Barrier!', 41, 0, 100, 0, 0, 0, 'Runic Colossus');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(32873, 0, 0, '%s fortifies nearby allies with runic might!', 41, 0, 100, 0, 0, 0, 'Ancient Rune Giant');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(32906, 0, 0, 'The Conservatory must be protected!', 14, 0, 100, 0, 0, 15526, 'Freya SAY_AGGRO'),
(32906, 1, 0, 'Elders grant me your strength!', 14, 0, 100, 0, 0, 15527, 'Freya SAY_AGGRO_WITH_ELDER'),
(32906, 2, 0, 'Forgive me.', 14, 0, 100, 0, 0, 15529, 'Freya SAY_SLAY_1'),
(32906, 2, 1, 'From your death springs life anew!', 14, 0, 100, 0, 0, 15530, 'Freya SAY_SLAY_2'),
(32906, 3, 0, 'His hold on me dissipates. I can see clearly once more. Thank you, heroes.', 14, 0, 100, 0, 0, 15531, 'Freya SAY_DEATH'),
(32906, 4, 0, 'You have strayed too far. Wasted too much time....', 14, 0, 100, 0, 0, 15532, 'Freya SAY_BERSERK'),
(32906, 5, 0, 'Eonar, your servant requires aid!', 14, 0, 100, 0, 0, 15528, 'Freya SAY_SUMMON_CONSERVATOR'),
(32906, 6, 0, 'Children, assist me!', 14, 0, 100, 0, 0, 15533, 'Freya SAY_SUMMON_TRIO'),
(32906, 7, 0, 'The swarm of the elements shall overtake you!', 14, 0, 100, 0, 0, 15534, 'Freya SAY_SUMMON_LASHERS'),
(32906, 8, 0, 'A |cFF00FFFFLifebinder\'s Gift|r begins to grow!', 41, 0, 100, 0, 0, 0, 'Freya EMOTE_LIFEBINDERS_GIFT'),
(32906, 9, 0, 'Allies of Nature have appeared!', 41, 0, 100, 0, 0, 0, 'Freya EMOTE_ALLIES_OF_NATURE'),
(32906, 10, 0, 'Freya begins to cast |cFFFF0000Ground Tremor!|r', 41, 0, 100, 0, 0, 0, 'Freya EMOTE_GROUND_TREMOR'),
(32906, 11, 0, 'Freya casts |cFF00FF00Strengthened Iron Roots!|r', 41, 0, 100, 0, 0, 0, 'Freya EMOTE_IRON_ROOTS');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(32914, 0, 0, 'This place will serve as your graveyard.', 14, 0, 100, 0, 0, 15500, 'Elder Stonebark SAY_AGGRO'),
(32914, 1, 0, '%s roars in anger!', 14, 0, 100, 0, 0, 15501, 'Elder Stonebark SAY_SLAY_1'),
(32914, 1, 1, 'Such a waste....', 14, 0, 100, 0, 0, 15502, 'Elder Stonebark SAY_SLAY_2'),
(32914, 2, 0, 'Matron, flee! They are ruthless....', 14, 0, 100, 0, 0, 15503, 'Elder Stonebark SAY_DEATH');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(32915, 0, 0, 'Matron, the Conservatory has been breached!', 14, 0, 100, 0, 0, 15483, 'Elder Brightleaf SAY_AGGRO'),
(32915, 1, 0, 'Fertilizer.', 14, 0, 100, 0, 0, 15485, 'Elder Brightleaf SAY_SLAY_1'),
(32915, 1, 1, 'Your corpse will nourish the soil.', 14, 0, 100, 0, 0, 15486, 'Elder Brightleaf SAY_SLAY_2'),
(32915, 2, 0, 'Matron, one has fallen!', 14, 0, 100, 0, 0, 15487, 'Elder Brightleaf SAY_DEATH');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(32927, 0, 0, 'Nothing short of total decimation will suffice.', 14, 0, 100, 0, 0, 15657, 'Runemaster Molgeim - Aggro'),
(32927, 1, 0, 'The world suffers yet another insignificant loss.', 14, 0, 100, 0, 0, 15658, 'Runemaster Molgeim - Slay 1'),
(32927, 1, 1, 'Death is the price of your arrogance.', 14, 0, 100, 0, 0, 15659, 'Runemaster Molgeim - Slay 2'),
(32927, 2, 0, 'Decipher this!', 14, 0, 100, 0, 0, 15660, 'Runemaster Molgeim - Rune of Death'),
(32927, 3, 0, 'Face the lightning\'s surge!', 14, 0, 100, 0, 0, 15661, 'Runemaster Molgeim - Rune of Summon'),
(32927, 4, 0, 'The legacy of storms shall not be undone.', 14, 0, 100, 0, 0, 15662, 'Runemaster Molgeim - Death'),
(32927, 5, 0, 'What have you gained from my defeat? You are no less doomed, mortals.', 14, 0, 100, 0, 0, 15663, 'Runemaster Molgeim - Encounter defeated'),
(32927, 6, 0, 'This meeting of the Assembly of Iron is adjourned!', 14, 0, 100, 0, 0, 15664, 'Runemaster Molgeim - Berserk');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(33113, 0, 0, 'Hostile entities detected. Threat assessment protocol active. Primary target engaged. Time minus 30 seconds to re-evaluation.', 14, 0, 100, 0, 0, 15506, 'Flame Leviathan SAY_AGGRO'),
(33113, 1, 0, 'Threat assessment routine modified. Current target threat level: 0. Acquiring new target.', 14, 0, 100, 0, 0, 15521, 'Flame Leviathan SAY_SLAY'),
(33113, 2, 0, 'Total systems failure. Defense protocols breached. Leviathan unit shutting down.', 14, 0, 100, 0, 0, 15520, 'Flame Leviathan SAY_DEATH'),
(33113, 3, 0, 'Threat re-evaluated. Target assessment complete. Changing course.', 14, 0, 100, 0, 0, 15507, 'Flame Leviathan SAY_TARGET_1'),
(33113, 3, 1, 'Pursuit objective modified. Changing course.', 14, 0, 100, 0, 0, 15508, 'Flame Leviathan SAY_TARGET_2'),
(33113, 3, 2, 'Hostile entity\'s stratagem predicted. Re-routing battle function. Changing course.', 14, 0, 100, 0, 0, 15509, 'Flame Leviathan SAY_TARGET_3'),
(33113, 4, 0, 'Orbital countermeasures enabled.', 14, 0, 100, 0, 0, 15510, 'Flame Leviathan SAY_HARDMODE'),
(33113, 5, 0, '*ALERT* Static defense system failure. Orbital countermeasures disabled.', 14, 0, 100, 0, 0, 15511, 'Flame Leviathan SAY_TOWER_NONE'),
(33113, 6, 0, 'Hodir\'s Fury online. Acquiring target.', 14, 0, 100, 0, 0, 15512, 'Flame Leviathan SAY_TOWER_FROST'),
(33113, 7, 0, 'Mimiron\'s Inferno online. Acquiring target.', 14, 0, 100, 0, 0, 15513, 'Flame Leviathan SAY_TOWER_FLAME'),
(33113, 8, 0, 'Freya\'s Ward online. Acquiring target.', 14, 0, 100, 0, 0, 15514, 'Flame Leviathan SAY_TOWER_NATURE'),
(33113, 9, 0, 'Thorim\'s Hammer online. Acquiring target.', 14, 0, 100, 0, 0, 15515, 'Flame Leviathan SAY_TOWER_STORM'),
(33113, 10, 0, 'Unauthorized entity attempting circuit overload. Activating anti-personnel countermeasures.', 14, 0, 100, 0, 0, 15516, 'Flame Leviathan SAY_PLAYER_RIDING'),
(33113, 11, 0, 'System malfunction. Diverting power to support systems.', 14, 0, 100, 0, 0, 15517, 'Flame Leviathan SAY_OVERLOAD_1'),
(33113, 11, 1, 'Combat matrix overload. Powering doooow...', 14, 0, 100, 0, 0, 15518, 'Flame Leviathan SAY_OVERLOAD_2'),
(33113, 11, 2, 'System restart required. Deactivating weapons systems.', 14, 0, 100, 0, 0, 15519, 'Flame Leviathan SAY_OVERLOAD_3'),
(33113, 12, 0, '%s pursues $n.', 41, 0, 100, 0, 0, 0, 'Flame Leviathan EMOTE_PURSUE'),
(33113, 13, 0, '%s\'s circuits overloaded.', 41, 0, 100, 0, 0, 0, 'Flame Leviathan EMOTE_OVERLOAD'),
(33113, 14, 0, 'Automatic repair sequence initiated.', 41, 0, 100, 0, 0, 0, 'Flame Leviathan EMOTE_REPAIR');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(33118, 0, 0, 'Insolent whelps! Your blood will temper the weapons used to reclaim this world!', 14, 0, 100, 0, 0, 15564, 'Ignis SAY_AGGRO'),
(33118, 1, 0, 'Arise, soldiers of the iron crucible! The Maker\'s will be done!', 14, 0, 100, 0, 0, 15565, 'Ignis SAY_SUMMON'),
(33118, 1, 1, '', 14, 0, 100, 0, 0, 15570, 'Ignis SAY_SLAY_2'),
(33118, 2, 0, 'I will burn away your impurities!', 14, 0, 100, 0, 0, 15566, 'Ignis SAY_SLAG_POT'),
(33118, 3, 0, 'Let the inferno consume you!', 14, 0, 100, 0, 0, 15567, 'Ignis SAY_SCORCH_1'),
(33118, 3, 1, 'BURN! Burn in the Maker\'s fire!', 14, 0, 100, 0, 0, 15568, 'Ignis SAY_SCORCH_2'),
(33118, 4, 0, 'More scraps for the scrap heap.', 14, 0, 100, 0, 0, 15569, 'Ignis SAY_SLAY_1'),
(33118, 4, 1, 'Your bones will serve as kindling.', 14, 0, 100, 0, 0, 15570, 'Ignis SAY_SLAY_2'),
(33118, 5, 0, 'LET IT BE FINISHED!', 14, 0, 100, 0, 0, 15571, 'Ignis SAY_BERSERK'),
(33118, 5, 1, '', 14, 0, 100, 0, 0, 15568, 'Ignis SAY_SCORCH_2'),
(33118, 6, 0, 'I. Have. Failed.', 14, 0, 100, 0, 0, 15572, 'Ignis SAY_DEATH'),
(33118, 7, 0, '%s begins to cast Flame Jets!', 41, 0, 100, 0, 0, 0, 'Ignis EMOTE_JETS');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(33134, 0, 0, 'HELP ME! Please get them off of me!', 14, 0, 100, 0, 0, 15771, 'Sara - SAY_SARA_ULDUAR_SCREAM_1'),
(33134, 1, 0, 'What do you want from me? Leave me alone!', 14, 0, 100, 0, 0, 15772, 'Sara - SAY_SARA_ULDUAR_SCREAM_2'),
(33134, 2, 0, 'The time to strike at the head of the beast will soon be upon us! Focus your anger and hatred on his minions!', 14, 0, 100, 457, 0, 15775, 'Sara - SAY_SARA_AGGRO'),
(33134, 3, 0, 'Yes! YES! Show them no mercy! Give no pause to your attacks!', 14, 0, 100, 0, 0, 15773, 'Sara - SAY_SARA_FERVOR_HIT'),
(33134, 4, 0, 'Let hatred and rage guide your blows!', 14, 0, 100, 0, 0, 15774, 'SAY_SARA_BLESSING_HIT'),
(33134, 5, 0, 'Could they have been saved?', 14, 0, 100, 0, 0, 15779, 'Sara - SAY_SARA_KILL'),
(33134, 5, 1, 'Powerless to act....', 14, 0, 100, 0, 0, 15778, 'Sara - SAY_SARA_KILL'),
(33134, 6, 0, 'I am the lucid dream.', 14, 0, 100, 457, 0, 15754, 'Sara - SAY_SARA_TRANSFORM_1'),
(33134, 7, 0, 'The monster in your nightmares.', 14, 0, 100, 457, 0, 0, 'Sara - SAY_SARA_TRANSFORM_2'),
(33134, 8, 0, 'The fiend of a thousand faces.', 14, 0, 100, 457, 0, 0, 'Sara - SAY_SARA_TRANSFORM_3'),
(33134, 9, 0, 'Cower before my true form.', 14, 0, 100, 457, 0, 0, 'Sara - SAY_SARA_TRANSFORM_4'),
(33134, 10, 0, 'Tremble, mortals, before the coming of the end!', 14, 0, 100, 0, 0, 15777, 'Sara - SAY_SARA_DEATH_RAY'),
(33134, 11, 0, 'Suffocate upon your own hate!', 14, 0, 100, 0, 0, 15776, 'Sara - SAY_SARA_PSYCHOSIS_HIT');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(33196, 0, 0, 'Thorim, my lord!  Why else would these invaders have come into your sanctum but to slay you?  They must be stopped!', 14, 0, 100, 0, 0, 15668, 'Sif - Start'),
(33196, 1, 0, 'These pathetic mortals are harmless, beneath my station.  Dispose of them!', 14, 0, 100, 0, 0, 15669, 'Sif - Despawn'),
(33196, 2, 0, 'Impossible!  Lord Thorim, I will bring your foes a frigid death!', 14, 0, 100, 0, 0, 15670, 'Sif - Event');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(33210, 0, 0, 'Welcome, champions! All of our attempts at bringing her down have failed. We could use a hand in bringing her down with these harpoon guns.', 12, 0, 100, 0, 0, 15647, 'Expedition Commander SAY_INTRO'),
(33210, 1, 0, 'Move quickly! She won\'t remain grounded for long!', 14, 0, 100, 0, 0, 15648, 'Expedition Commander SAY_GROUND_PHASE'),
(33210, 2, 0, 'Be on the lookout! Mole machines will be surfacing soon with those nasty Iron dwarves aboard!', 14, 0, 100, 0, 0, 0, 'Expedition Commander SAY_AGGRO_2');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(33242, 0, 0, 'As you wish, $n.', 12, 0, 100, 0, 0, 0, 'Thorim (Observation Ring) - On Gossip Select'),
(33242, 1, 0, 'Golganneth, lend me your strength! Grant my mortal allies the power of thunder!', 14, 0, 100, 0, 0, 15750, 'Thorim (Observation Ring) - On Gossip Select');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(33271, 0, 0, 'Your destruction will herald a new age of suffering!', 14, 0, 100, 0, 0, 15542, 'General Vezax SAY_AGGRO'),
(33271, 1, 0, 'You thought to stand before the legions of death and survive?', 14, 0, 100, 0, 0, 15543, 'General Vezax SAY_SLAY_1'),
(33271, 1, 1, 'Defiance... a flaw of mortality.', 14, 0, 100, 0, 0, 15544, 'General Vezax SAY_SLAY_2'),
(33271, 2, 0, 'The black blood of Yogg-Saron courses through me! I. AM. UNSTOPPABLE!', 14, 0, 100, 0, 0, 15545, 'General Vezax SAY_SURGE_OF_DARKNESS'),
(33271, 3, 0, 'Oh, what horrors await....', 14, 0, 100, 0, 0, 15546, 'General Vezax SAY_DEATH'),
(33271, 4, 0, 'Your defeat was inevitable.', 14, 0, 100, 0, 0, 15547, 'General Vezax SAY_BERSERK'),
(33271, 5, 0, 'Behold now: terror absolute!', 14, 0, 100, 0, 0, 15548, 'General Vezax SAY_HARDMODE'),
(33271, 6, 0, 'The saronite vapors mass and swirl violently, merging into a monstrous form!', 41, 0, 100, 0, 0, 0, 'General Vezax - EMOTE_ANIMUS'),
(33271, 7, 0, 'A saronite barrier appears around General Vezax!', 41, 0, 100, 0, 0, 0, 'General Vezax - EMOTE_BARRIER'),
(33271, 8, 0, 'General Vezax roars and surges with dark might!', 41, 0, 100, 0, 0, 0, 'General Vezax - EMOTE_SURGE_OF_DARKNESS');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(33280, 0, 0, 'Weak-minded fool!', 15, 0, 100, 0, 0, 15780, 'Voice of Yogg-Saron - WHISPER_VOICE_PHASE_1_WIPE'),
(33280, 1, 0, 'Your will is no longer your own.', 15, 0, 100, 0, 0, 15759, 'Voice of Yogg-Saron - WHISPER_VOICE_INSANE'),
(33280, 1, 1, 'Destroy them, minion! Your master commands it!', 15, 0, 100, 0, 0, 15760, 'Voice of Yogg-Saron - WHISPER_VOICE_INSANE');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(33288, 0, 0, 'BOW DOWN BEFORE THE GOD OF DEATH!', 14, 0, 100, 0, 0, 0, 'Yogg-Saron - SAY_YOGG_SARON_SPAWN'),
(33288, 1, 0, 'MADNESS WILL CONSUME YOU!', 14, 0, 100, 0, 0, 15756, 'Yogg-Saron - SAY_YOGG_SARON_MADNESS'),
(33288, 2, 0, 'Portals open into %s\'s mind!', 41, 0, 100, 0, 0, 0, 'Yogg-Saron - EMOTE_YOGG_SARON_MADNESS'),
(33288, 3, 0, 'Look upon the true face of death, and know that your end comes soon!', 14, 0, 100, 0, 0, 15755, 'Yogg-Saron - SAY_YOGG_SARON_PHASE_3'),
(33288, 4, 0, 'Eternal suffering awaits!', 14, 0, 100, 0, 0, 15758, 'Yogg-Saron - SAY_YOGG_SARON_DEAFENING_ROAR'),
(33288, 5, 0, '%s opens his mouth wide!', 41, 0, 100, 0, 0, 0, 'Yogg-Saron - EMOTE_YOGG_SARON_DEAFENING_ROAR'),
(33288, 6, 0, 'Your fate is sealed. The end of days is finally upon you and ALL who inhabit this miserable little seedling. Uulwi ifis halahs gag erh\'ongg w\'ssh.', 14, 0, 100, 0, 0, 15761, 'Yogg-Saron - SAY_YOGG_SARON_DEATH'),
(33288, 7, 0, '%s prepares to unleash Empowering Shadows!', 41, 0, 100, 0, 0, 0, 'Yogg-Saron - EMOTE_YOGG_SARON_EMPOWERING_SHADOWS'),
(33288, 8, 0, '%s goes berserk, extinguishing all life!', 41, 0, 100, 0, 0, 0, 'Yogg-Saron - EMOTE_YOGG_SARON_EXTINGUISH_ALL_LIFE');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(33350, 0, 0, 'Oh, my! I wasn\'t expecting company! The workshop is such a mess. How embarrassing.', 14, 0, 100, 0, 0, 15611, 'Mimiron SAY_AGGRO'),
(33350, 1, 0, 'Now, why would you go and do something like that? Didn\'t you see the sign that said, \"DO NOT PUSH THIS BUTTON!\"? How will we finish testing with the self-destruct mechanism active?', 14, 0, 100, 0, 0, 15629, 'Mimiron SAY_HARDMODE_ON'),
(33350, 2, 0, 'We haven\'t much time, friends! You\'re going to help me test out my latest and greatest creation. Now, before you change your minds, remember that you kind of owe it to me after the mess you made with the XT-002.', 14, 0, 100, 0, 0, 15612, 'Mimiron SAY_MKII_ACTIVATE'),
(33350, 3, 0, 'MEDIC!', 14, 0, 100, 0, 0, 15613, 'Mimiron SAY_MKII_SLAY_1'),
(33350, 3, 1, 'I can fix that... or  maybe not! Sheesh, what a mess...', 14, 0, 100, 0, 0, 15614, 'Mimiron SAY_MKII_SLAY_2'),
(33350, 4, 0, 'WONDERFUL! Positively marvelous results! Hull integrity at 98.9 percent! Barely a dent! Moving right along.', 14, 0, 100, 0, 0, 15615, 'Mimiron SAY_MKII_DEATH'),
(33350, 5, 0, 'Behold the VX-001 Anti-personnel Assault Cannon! You might want to take cover.', 14, 0, 100, 0, 0, 15616, 'Mimiron SAY_VX001_ACTIVATE'),
(33350, 6, 0, 'Fascinating. I think they call that a \"clean kill\".', 14, 0, 100, 0, 0, 15617, 'Mimiron SAY_VX001_SLAY_1'),
(33350, 6, 1, 'Note to self: Cannon highly effective against flesh.', 14, 0, 100, 0, 0, 15618, 'Mimiron SAY_VX001_SLAY_2'),
(33350, 7, 0, 'Thank you, friends! Your efforts have yielded some fantastic data! Now, where did I put-- oh, there it is.', 14, 0, 100, 0, 0, 15619, 'Mimiron SAY_VX001_DEATH'),
(33350, 8, 0, 'Isn\'t it beautiful? I call it the magnificent aerial command unit!', 14, 0, 100, 0, 0, 15620, 'Mimiron SAY_AERIAL_ACTIVATE'),
(33350, 9, 0, 'Outplayed!', 14, 0, 100, 0, 0, 15621, 'Mimiron SAY_AERIAL_SLAY_1'),
(33350, 9, 1, 'You can do better than that!', 14, 0, 100, 0, 0, 15622, 'Mimiron SAY_AERIAL_SLAY_2'),
(33350, 10, 0, 'Preliminary testing phase complete. Now comes the true test!', 14, 0, 100, 0, 0, 15623, 'Mimiron SAY_AERIAL_DEATH'),
(33350, 11, 0, 'Gaze upon its magnificence! Bask in its glorious, um, glory! I present you with... V-07-TR-0N!', 14, 0, 100, 0, 0, 15624, 'Mimiron SAY_V07TRON_ACTIVATE'),
(33350, 12, 0, 'Prognosis: Negative!', 14, 0, 100, 0, 0, 15625, 'Mimiron SAY_V07TRON_SLAY_1'),
(33350, 12, 1, 'You\'re not going to get up from that one, friend.', 14, 0, 100, 0, 0, 15626, 'Mimiron SAY_V07TRON_SLAY_2'),
(33350, 13, 0, 'It would appear that I\'ve made a slight miscalculation. I allowed my mind to be corrupted by the fiend in the prison, overriding my primary directive. All systems seem to be functional now. Clear.', 14, 0, 100, 0, 0, 15627, 'Mimiron SAY_V07TRON_DEATH'),
(33350, 14, 0, 'Oh, my! It would seem that we are out of time, my friends.', 14, 0, 100, 0, 0, 15628, 'Mimiron SAY_BERSERK');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(33436, 0, 0, 'Bad news, sire.', 12, 0, 100, 66, 0, 15538, 'Garona'),
(33436, 1, 0, 'The clans are united under Blackhand in this assault. They will stand together until Stormwind has fallen.', 12, 0, 100, 274, 0, 15539, 'Garona'),
(33436, 2, 0, 'Gul\'dan is bringing up his warlocks by nightfall. Until then, the Blackrock clan will be trying to take the Eastern Wall.', 12, 0, 100, 1, 0, 15540, 'Garona'),
(33436, 3, 0, 'The orc leaders agree with your assessment.', 12, 0, 100, 0, 0, 15541, 'Garona');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(33515, 0, 0, 'Some things are better left alone!', 14, 0, 100, 0, 0, 15473, 'Auriaya SAY_AGGRO'),
(33515, 1, 1, 'The secret dies with you.', 14, 0, 100, 0, 0, 15474, 'Auriaya SAY_SLAY_1'),
(33515, 1, 2, 'There is no escape!', 14, 0, 100, 0, 0, 15475, 'Auriaya SAY_SLAY_2'),
(33515, 2, 0, '%s screams in agony as the harpoon is removed.', 16, 0, 100, 0, 0, 15476, 'Auriaya SAY_DEATH'),
(33515, 3, 0, 'You waste my time!', 14, 0, 100, 0, 0, 15477, 'Auriaya SAY_BERSERK'),
(33515, 4, 0, '%s begins to cast Terrifying Screech.', 41, 0, 100, 0, 0, 0, 'Auriaya EMOTE_FEAR'),
(33515, 5, 0, '%s begins to activate the Feral Defender!', 41, 0, 100, 0, 0, 0, 'Auriaya EMOTE_DEFENDER');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(33552, 0, 0, 'A thousand deaths....', 12, 0, 100, 0, 0, 15762, 'Yogg-Saron'),
(33552, 1, 0, 'Your petty quarrels only make me stronger.', 12, 0, 100, 0, 0, 15764, 'Yogg-Saron'),
(33552, 2, 0, 'Yrr n\'lyeth... shuul anagg!', 12, 0, 100, 0, 0, 15766, 'Yogg-Saron'),
(33552, 3, 0, 'He will learn... no king rules forever; only death is eternal!', 12, 0, 100, 0, 0, 15767, 'Yogg-Saron'),
(33552, 4, 0, 'His brood learned their lesson before too long. You will soon learn yours!', 12, 0, 100, 0, 0, 15765, 'Yogg-Saron');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(33579, 0, 0, 'Pentarus, you heard the $gman:woman;. Have your mages release the shield and let these brave souls through!', 14, 0, 100, 0, 0, 0, ''),
(33579, 1, 0, 'Okay! Let\'s move out. Get into your machines; I\'ll speak to you from here via the radio!', 12, 0, 100, 0, 0, 15807, ''),
(33579, 2, 0, 'Our allies are ready. Bring down the shield and make way!', 14, 0, 100, 0, 0, 0, ''),
(33579, 3, 0, 'The iron dwarves have been seen emerging from the bunkers at the base of the pillars straight ahead of you! Destroy the bunkers, and they\'ll be forced to fall back!', 12, 0, 100, 0, 0, 15794, ''),
(33579, 4, 0, 'There are four generators powering the defense structures. If you sabotage the generators, the missile attacks will stop!', 12, 0, 100, 0, 0, 15796, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(33626, 0, 0, 'Not a bit. For the life of me, I can\'t figure out how this thing works.', 12, 0, 100, 0, 0, 0, 'Hired Engineer to Player'),
(33626, 1, 0, 'I know, I know... I haven\'t given up yet. Don\'t get your hopes up though, this technology is way beyond me.', 12, 0, 100, 0, 0, 0, 'Hired Engineer to Player'),
(33626, 2, 0, 'The darned thing just started working! This should take you right up to the end of the concourse, where you last fought the Flame Leviathan.', 12, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(33662, 0, 0, 'Any luck?', 12, 0, 100, 0, 0, 0, 'Kirin Tor Battle-Mage to Player'),
(33662, 1, 0, 'Keep at it. If our suspicions are right and this is a transporter, it could prove extremely useful in our assault.', 12, 0, 100, 0, 0, 0, 'Kirin Tor Battle-Mage to Player');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(33686, 0, 0, 'I was constructed to serve as a repository for essential information regarding this complex. My primary functions include communicating the status of the frontal defense systems and assessing the status of the entity that this complex was built to imprison.', 12, 0, 0, 0, 0, 0, 'Norgannon SAY_EVENT_1'),
(33686, 1, 0, 'Access to the interior of the complex is currently restricted. Primary defensive emplacements are active. Secondary systems are currently non-active.', 12, 0, 0, 0, 0, 0, 'Norgannon SAY_EVENT_2'),
(33686, 2, 0, 'Compromise of complex detected, security override enabled - query permitted.', 12, 0, 0, 0, 0, 0, 'Norgannon SAY_EVENT_3'),
(33686, 3, 0, 'Primary defensive emplacements consist of iron constructs and Storm Beacons, which will generate additional constructs as necessary. Secondary systems consist of orbital defense emplacements.', 12, 0, 0, 0, 0, 0, 'Norgannon SAY_EVENT_4'),
(33686, 4, 0, 'Entity designate: Yogg-Saron. Security has been compromised. Prison operational status unknown. Unable to contact Watchers for notification purposes.', 12, 0, 0, 0, 0, 0, 'Norgannon SAY_EVENT_5'),
(33686, 7, 0, 'Entity designate: Yogg-Saron. Security has been compromised. Prison operational status unknown. Unable to contact Watchers for notification purposes.', 12, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(33701, 0, 0, 'I heard a story or two of a Lore Keeper in Uldaman that fit your description. Do you serve a similar purpose?', 12, 0, 100, 0, 0, 0, 'High Explorer Dellorah to Player'),
(33701, 1, 0, 'Frontal defense systems? Is there something I should let Brann know before he has anyone attempt to enter the complex?', 12, 0, 100, 0, 0, 0, 'High Explorer Dellorah to Player'),
(33701, 2, 0, 'Can you detail the nature of these defense systems?', 12, 0, 100, 0, 0, 0, 'High Explorer Dellorah to Player'),
(33701, 3, 0, 'Got it. At least we don\'t have to deal with those orbital emplacements.', 12, 0, 100, 0, 0, 0, 'High Explorer Dellorah to Player'),
(33701, 4, 0, 'Rhydian, make sure you let Brann and Archmage Pentarus know about those defenses immediately.', 12, 0, 100, 0, 0, 0, 'High Explorer Dellorah to Player'),
(33701, 5, 0, 'And you mentioned an imprisoned entity? What is the nature of this entity and what is its status?', 12, 0, 100, 0, 0, 0, 'High Explorer Dellorah to Player'),
(33701, 6, 0, 'Yogg-Saron is here? It sounds like we really will have our hands full then.', 12, 0, 100, 0, 0, 0, 'High Explorer Dellorah to Player'),
(33701, 7, 0, 'Yogg-Saron is here? It sounds like we really will have our hands full then.', 12, 0, 100, 0, 0, 0, ''),
(33701, 8, 0, 'What... What did you just do, $n?! Brann! Braaaaannn!', 14, 0, 100, 0, 0, 0, ''),
(33701, 9, 0, 'Brann! $n just activated the orbital defense system! If we don\'t get out of here soon, we\'re going to be toast!', 14, 0, 100, 0, 0, 0, ''),
(33701, 10, 0, 'Looks like the battle\'s about to get under way, that\'s my cue to leave. We\'ll have to pick this up later.', 12, 0, 100, 0, 0, 0, '');
INSERT INTO `achievement_criteria_data` (`criteria_id`, `type`, `value1`, `value2`, `ScriptName`) VALUES
(10046, 11, 0, 0, 'achievement_three_car_garage_chopper'),
(10047, 11, 0, 0, 'achievement_three_car_garage_siege'),
(10048, 11, 0, 0, 'achievement_three_car_garage_demolisher'),
